{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "requirements_spec",
  "description": "A normalized, testable statement of what to build. Every requirement has a stable id.",
  "type": "object",
  "additionalProperties": false,
  "required": ["problemStatement", "functional", "nonFunctional", "acceptanceCriteria", "assumptions",
               "ambiguities", "outOfScope", "classification"],
  "properties": {
    "problemStatement": { "type": "string", "minLength": 1 },
    "functional": {
      "type": "array", "minItems": 1,
      "items": {
        "type": "object", "additionalProperties": false, "required": ["id", "text", "priority"],
        "properties": {
          "id": { "type": "string", "pattern": "^FR-[0-9]+$" },
          "text": { "type": "string", "minLength": 1 },
          "priority": { "enum": ["MUST", "SHOULD", "COULD"] }
        }
      }
    },
    "nonFunctional": {
      "type": "array",
      "items": {
        "type": "object", "additionalProperties": false, "required": ["id", "text", "category"],
        "properties": {
          "id": { "type": "string", "pattern": "^NFR-[0-9]+$" },
          "text": { "type": "string", "minLength": 1 },
          "category": { "enum": ["PERFORMANCE", "SECURITY", "RELIABILITY", "PRIVACY", "OPERABILITY", "COMPATIBILITY", "OTHER"] }
        }
      }
    },
    "acceptanceCriteria": {
      "type": "array", "minItems": 1,
      "items": {
        "type": "object", "additionalProperties": false, "required": ["id", "requirementId", "given", "when", "then"],
        "properties": {
          "id": { "type": "string", "pattern": "^AC-[0-9]+$" },
          "requirementId": { "type": "string", "pattern": "^N?FR-[0-9]+$" },
          "given": { "type": "string" },
          "when": { "type": "string" },
          "then": { "type": "string" }
        }
      }
    },
    "assumptions": { "type": "array", "items": { "type": "string", "minLength": 1 } },
    "ambiguities": {
      "type": "array",
      "items": {
        "type": "object", "additionalProperties": false,
        "required": ["id", "question", "options", "severity", "proposedDefault"],
        "properties": {
          "id": { "type": "string", "pattern": "^AMB-[0-9]+$" },
          "question": { "type": "string", "minLength": 1 },
          "options": { "type": "array", "items": { "type": "string" } },
          "severity": { "enum": ["BLOCKING", "NONBLOCKING"] },
          "proposedDefault": { "type": "string" }
        }
      }
    },
    "outOfScope": { "type": "array", "items": { "type": "string", "minLength": 1 } },
    "classification": { "enum": ["GREENFIELD", "BROWNFIELD"] }
  }
}

response.text:
{
  "problemStatement": "People create short links to malicious destinations. Refuse links to blocklisted domains and to other URL shorteners (whose final destination these checks cannot see) when they are created, and let an admin flag an existing abusive link so that it stops redirecting (451). No external reputation API and no rescan of existing links.",
  "functional": [
    {
      "id": "FR-1",
      "text": "Creating a link whose destination host is a blocklisted domain, or a subdomain of one, is refused with 400 invalid-url and reason BLOCKED_DOMAIN. The blocklist is configuration (shortener.abuse.blocked-domains), matched case-insensitively.",
      "priority": "MUST"
    },
    {
      "id": "FR-2",
      "text": "Creating a link to another URL shortener (bit.ly, tinyurl.com, t.co and other listed shortener domains, or subdomains of them) is refused with 400 invalid-url and reason URL_SHORTENER; the list is configuration (shortener.abuse.shortener-domains) with the common public shorteners as its default.",
      "priority": "MUST"
    },
    {
      "id": "FR-3",
      "text": "An admin can flag a link with POST /api/v1/admin/links/{code}/flag (204, idempotent); only API keys named in shortener.abuse.admin-keys may, others get 403 forbidden.",
      "priority": "MUST"
    },
    {
      "id": "FR-4",
      "text": "A flagged link answers 451 with type /problems/link-unavailable on redirect, from the next request on, even if it was cached.",
      "priority": "MUST"
    },
    {
      "id": "FR-5",
      "text": "The owner sees a flagged link with status FLAGGED; unknown and deleted links cannot be flagged (404).",
      "priority": "SHOULD"
    }
  ],
  "nonFunctional": [
    {
      "id": "NFR-1",
      "text": "The checks add no network call: the blocklist is matched in memory and the redirect path is unchanged for active links.",
      "category": "PERFORMANCE"
    },
    {
      "id": "NFR-2",
      "text": "Every flag is logged with the admin key that set it.",
      "category": "OPERABILITY"
    }
  ],
  "acceptanceCriteria": [
    {
      "id": "AC-1",
      "requirementId": "FR-1",
      "given": "evil.test on the blocklist",
      "when": "links to https://evil.test/login and https://www.EVIL.test/x are created",
      "then": "400 invalid-url with reason BLOCKED_DOMAIN"
    },
    {
      "id": "AC-2",
      "requirementId": "FR-1",
      "given": "evil.test on the blocklist",
      "when": "a link to https://notevil.test/ is created",
      "then": "201: a suffix is not a subdomain"
    },
    {
      "id": "AC-3",
      "requirementId": "FR-2",
      "given": "the default shortener list",
      "when": "links to https://bit.ly/abc, https://t.co/y and https://go.bit.ly/z are created",
      "then": "400 invalid-url with reason URL_SHORTENER; a link to this service itself stays SELF_REFERENCE"
    },
    {
      "id": "AC-4",
      "requirementId": "FR-3",
      "given": "an admin key",
      "when": "it flags an active link",
      "then": "204, and again 204 when repeated"
    },
    {
      "id": "AC-5",
      "requirementId": "FR-3",
      "given": "a key that is not an admin key",
      "when": "it flags a link",
      "then": "403 forbidden and the link still redirects; 401 without a key"
    },
    {
      "id": "AC-6",
      "requirementId": "FR-4",
      "given": "a link that has redirected once (cached)",
      "when": "an admin flags it and GET /{code}",
      "then": "451 link-unavailable, on every later request too"
    },
    {
      "id": "AC-7",
      "requirementId": "FR-5",
      "given": "a flagged link",
      "when": "its owner GETs /api/v1/links/{code}",
      "then": "status FLAGGED"
    },
    {
      "id": "AC-8",
      "requirementId": "FR-5",
      "given": "an unknown or a deleted link",
      "when": "an admin flags it",
      "then": "404 link-not-found"
    }
  ],
  "assumptions": [
    "Admins are API keys listed by name; there is no separate admin login.",
    "A flagged link stays FLAGGED; unflagging is out of scope.",
    "The cross-instance L1 window of BF-1 also applies to flags: other instances may redirect a just-flagged link for up to the L1 TTL."
  ],
  "ambiguities": [],
  "outOfScope": [
    "External reputation APIs",
    "Rescanning existing links",
    "Spam account detection",
    "Unflagging"
  ],
  "classification": "BROWNFIELD"
}
